{
  "skills": [
    {
      "skill_id": "moss_inverse_polarizability_gap",
      "rules": [
        {
          "rule_id": "chalcogenide_polarizable_narrow_gap",
          "conditions": {"anion_family": "chalcogenide"},
          "weight": -0.55,
          "rationale": "Source shows chalcogenides raise refractive index; Moss relation implies high polarizability accompanies narrow band gaps."
        },
        {
          "rule_id": "halide_ionic_wide_gap",
          "conditions": {"anion_family": "halide"},
          "weight": 0.5,
          "rationale": "Halides had negative refractive-index effect; deep ionic halogen p bands give wide experimental gaps."
        },
        {
          "rule_id": "very_heavy_lattice_narrow_gap",
          "conditions": {"mean_atomic_number_bin": "mean_z_very_high"},
          "weight": -0.45,
          "rationale": "Heavy diffuse valence orbitals and strong spin-orbit splitting compress gaps while boosting refractive index."
        },
        {
          "rule_id": "light_nonmetal_covalent_wide_gap",
          "conditions": {"dominant_family": "light_nonmetal"},
          "weight": 0.4,
          "rationale": "Light second-row nonmetal networks (B, C, N, O) show large sp bonding splitting and wide gaps."
        }
      ],
      "ridge": 1.2,
      "prior_scale": 0.26,
      "semantic_mass_start": 0.28,
      "semantic_mass_end": 0.08,
      "ucb_weight": 0.55,
      "gp_beta_start": 2.2,
      "gp_beta_end": 1.1,
      "gp_xi": 0.02,
      "confidence": 0.6,
      "hypothesis": "Transfers source refractive-index effects with reversed sign via the Moss relation: polarizable heavy chalcogenides narrow gaps while ionic halides and light nonmetals widen them. Fails if dataset halides are heavy iodides or metallic."
    },
    {
      "skill_id": "metallicity_penalty_anchor_lean",
      "rules": [
        {
          "rule_id": "partial_d_band_penalty",
          "conditions": {"transition_metal_flag": "has_transition_metal"},
          "weight": -0.35,
          "rationale": "Partially filled d bands introduce states near the Fermi level, systematically narrowing experimental gaps."
        },
        {
          "rule_id": "metal_chalcogenide_narrow_gap",
          "conditions": {"transition_metal_flag": "has_transition_metal", "anion_family": "chalcogenide"},
          "weight": -0.4,
          "rationale": "Transition-metal sulfides/selenides hybridise d with chalcogen p, yielding small or vanishing gaps."
        },
        {
          "rule_id": "oxide_ionic_insulator_boost",
          "conditions": {"anion_family": "oxide"},
          "weight": 0.35,
          "rationale": "Oxide O 2p valence bands lie deep, giving the widest gaps among common anion chemistries."
        },
        {
          "rule_id": "heavy_lattice_mild_penalty",
          "conditions": {"mean_atomic_number_bin": "mean_z_high"},
          "weight": -0.25,
          "rationale": "Higher mean Z correlates with diffuse bonding and reduced bonding-antibonding separation; source transfer weight here is moderate."
        }
      ],
      "ridge": 1.5,

